-- 方案C批2-F：RLS policy key 统一（app.current_tenant_id -> app.tenant_id）
-- 背景：15 张表的 rls_tenant_isolation 用旧 key app.current_tenant_id，而 8 txn crate 事务内 SET 的是 app.tenant_id
--       旧 key 分支永不匹配 -> txn 内读非 nil 租户行被 RLS 滤（隔离过度）；pool 直连已由批2-E nil 分支兼容
-- 修复：policy 表达式中的 current_setting('app.current_tenant_id') 全部替换为 current_setting('app.tenant_id')
--       使 txn SET app.tenant_id 后读匹配租户行放行、其他租户行过滤（隔离语义正确）
-- 生成方式：python 读取 pg_policy 现状，字符串替换生成

ALTER POLICY "rls_tenant_isolation" ON ai.ai_models USING (((current_setting('app.tenant_id'::text, true) IS NULL) OR (current_setting('app.tenant_id'::text, true) = ''::text) OR (tenant_id IS NULL) OR (tenant_id = (NULLIF(current_setting('app.tenant_id'::text, true), ''::text))::uuid) OR (NULLIF(current_setting('app.tenant_id'::text, true), ''::text) = '00000000-0000-0000-0000-000000000000'::text))) WITH CHECK (((current_setting('app.tenant_id'::text, true) IS NULL) OR (current_setting('app.tenant_id'::text, true) = ''::text) OR (tenant_id IS NULL) OR (tenant_id = (NULLIF(current_setting('app.tenant_id'::text, true), ''::text))::uuid) OR (NULLIF(current_setting('app.tenant_id'::text, true), ''::text) = '00000000-0000-0000-0000-000000000000'::text)));
